import { describe, expect, it } from "vitest"
import { bangDataOf, serializedBangData } from "./bang-data"

const heliumList = (body: string) =>
  [
    "// Generated at 2026-10-14T11:11:02.825Z",
    "// DO NOT edit this file manually! This file is automatically generated.",
    "//",
    "// MIT License",
    "//",
    "// Copyright (c) 2024 Kagi Search, 2026 imput",
    "",
    body,
  ].join("\n")

describe("reading Helium's list of bangs", () => {
  it("keeps each bang's name, triggers and URL, with %s where the search terms go", () => {
    const list = heliumList(`[
 {
  "s": "GitHub",
  "ts": [
   "gh",
   "github",
  ],
  "u": "https://github.com/search?q={searchTerms}"
 },
]`)

    expect(bangDataOf(list).entries).toStrictEqual([
      ["GitHub", ["gh", "github"], "https://github.com/search?q=%s"],
    ])
  })

  it("keeps the format flags of the bangs that set them", () => {
    const list = heliumList(`[
 { "s": "Wayback Machine", "ts": [ "wb" ], "f": 1, "u": "https://web.archive.org/web/*/{searchTerms}" }
]`)

    expect(bangDataOf(list).entries).toStrictEqual([
      ["Wayback Machine", ["wb"], "https://web.archive.org/web/*/%s", 1],
    ])
  })

  it("takes the license from the comments, from its title down", () => {
    const list = heliumList(`[]`)

    expect(bangDataOf(list).license).toBe(
      "MIT License\n\nCopyright (c) 2024 Kagi Search, 2026 imput\n",
    )
  })

  it("refuses a list without a license", () => {
    expect(() => bangDataOf(`[]`)).toThrow(/no license/)
  })

  it("refuses a bang whose URL has nowhere to put the search terms", () => {
    const list = heliumList(`[{ "s": "Example", "ts": ["ex"], "u": "https://example.com/" }]`)

    expect(() => bangDataOf(list)).toThrow(/!ex/)
  })

  it("refuses a bang whose URL has a literal %s, which would be taken for the search terms", () => {
    const list = heliumList(
      `[{ "s": "Example", "ts": ["ex"], "u": "https://example.com/%s?q={searchTerms}" }]`,
    )

    expect(() => bangDataOf(list)).toThrow(/literal %s/)
  })

  it("refuses a bang that opens anything but a web page", () => {
    const list = heliumList(`[{ "s": "Script", "ts": ["js"], "u": "javascript:{searchTerms}" }]`)

    expect(() => bangDataOf(list)).toThrow(/!js/)
  })
})

describe("the bundled file", () => {
  it("is a JSON array with one bang on each line", () => {
    const text = serializedBangData([
      ["GitHub", ["gh"], "https://github.com/search?q=%s"],
      ["Wayback Machine", ["wb"], "https://web.archive.org/web/*/%s", 1],
    ])

    expect(text.split("\n")).toStrictEqual([
      "[",
      '["GitHub",["gh"],"https://github.com/search?q=%s"],',
      '["Wayback Machine",["wb"],"https://web.archive.org/web/*/%s",1]',
      "]",
      "",
    ])
    expect(JSON.parse(text)).toHaveLength(2)
  })
})
